What will be the output of the following Java program?
public class CalculateN {
  public static void main(String[] args) {
    int n = 0, m = 4;
    for (int i = m + 5; i >= 6; i--) {
      if (i % 3 == 0) { n = n + i; }
      else { n = n - i; }
      System.out.println("n = " + n);
    }
  }
}
